INSERT INTO questions (id, text, difficulty, topic, explanation, points_base, is_active) VALUES
('10000000-0000-0000-0000-000000000001', 'What command initializes a new Git repository in the current working directory?', 'easy', 'basics', 'git init creates a new .git directory containing Git object database and metadata.', 1000, TRUE),
('10000000-0000-0000-0000-000000000002', 'Which command shows the chronological commit history of the current repository?', 'easy', 'basics', 'git log displays committed history in reverse chronological order.', 1000, TRUE),
('10000000-0000-0000-0000-000000000003', 'Which command stages all modified and newly created files in the repository?', 'easy', 'staging', 'git add . stages all modified and untracked files in the current repository path into the index.', 1000, TRUE),
('10000000-0000-0000-0000-000000000004', 'Which command records staged snapshots with an inline descriptive message?', 'easy', 'commits', 'git commit -m "message" records staged changes to project history with a commit message.', 1000, TRUE),
('10000000-0000-0000-0000-000000000005', 'What command copies an existing remote repository onto your local machine?', 'easy', 'cloning', 'git clone downloads the remote repository including its entire commit history into a new directory.', 1000, TRUE),
('10000000-0000-0000-0000-000000000006', 'What command creates a new branch named feature-login and immediately switches to it?', 'easy', 'branching', 'git checkout -b feature-login (or git switch -c feature-login) creates and activates the new branch.', 1000, TRUE),
('10000000-0000-0000-0000-000000000007', 'Which command lists all existing local branches in your repository?', 'easy', 'branching', 'git branch lists all local branches, marking the currently checked out branch with an asterisk.', 1000, TRUE),
('10000000-0000-0000-0000-000000000008', 'You have uncommitted modifications that you want to set aside without committing. What command do you run?', 'easy', 'stashing', 'git stash saves uncommitted modifications to a stack and restores the working tree to HEAD.', 1000, TRUE),
('10000000-0000-0000-0000-000000000009', 'What command restores the most recently stashed changes and removes them from the stash list?', 'easy', 'stashing', 'git stash pop reapplies the newest stash entry (stash@{0}) and removes it from the stash stack.', 1000, TRUE),
('10000000-0000-0000-0000-000000000010', 'Which command lists all currently stashed change sets in your repository?', 'easy', 'stashing', 'git stash list displays all saved stash entries along with their reference names.', 1000, TRUE),
('10000000-0000-0000-0000-000000000011', 'Which command displays the state of the working directory and the staging area?', 'easy', 'status', 'git status shows staged, unstaged, and untracked file statuses.', 1000, TRUE),
('10000000-0000-0000-0000-000000000012', 'Which command shows differences between your working directory modifications and staged files?', 'easy', 'diff', 'git diff displays changes in the working directory that have not yet been staged.', 1000, TRUE),
('10000000-0000-0000-0000-000000000013', 'Which command shows differences between staged modifications and the last commit?', 'easy', 'diff', 'git diff --staged (or --cached) inspects differences staged in the index against HEAD.', 1000, TRUE),
('10000000-0000-0000-0000-000000000014', 'What command shows all configured remote repository names along with their fetch/push URLs?', 'easy', 'remotes', 'git remote -v lists remote names and their associated URLs.', 1000, TRUE),
('10000000-0000-0000-0000-000000000015', 'What is the command to link a remote repository URL named origin to your local repo?', 'easy', 'remotes', 'git remote add origin <url> registers the remote repository URL under the alias origin.', 1000, TRUE),
('10000000-0000-0000-0000-000000000016', 'What is the primary difference between git fetch and git pull?', 'easy', 'remotes', 'git fetch only downloads objects from the remote without merging them into your working files.', 1000, TRUE),
('10000000-0000-0000-0000-000000000017', 'What does the -u flag do in git push -u origin main?', 'easy', 'remotes', '-u sets up upstream tracking references between the local branch and origin/main.', 1000, TRUE),
('10000000-0000-0000-0000-000000000018', 'What is the purpose of the .gitignore file in a project repository?', 'easy', 'ignore', '.gitignore specifies intentionally untracked patterns that Git should ignore.', 1000, TRUE),
('10000000-0000-0000-0000-000000000019', 'Which command sets your global commit author name across all Git repositories on your computer?', 'easy', 'config', 'git config --global user.name sets the author name stored in commits system-wide for the user.', 1000, TRUE),
('10000000-0000-0000-0000-000000000020', 'How can you view all resolved Git configuration settings in your terminal?', 'easy', 'config', 'git config --list prints all configuration variables from system, global, and local files.', 1000, TRUE),
('10000000-0000-0000-0000-000000000021', 'What command modifies the most recent commit by combining it with current staged changes?', 'easy', 'commits', 'git commit --amend combines staged modifications with the tip commit and allows updating message.', 1000, TRUE),
('10000000-0000-0000-0000-000000000022', 'Which command creates a lightweight tag named v1.0 pointing to the current commit?', 'easy', 'tags', 'git tag v1.0 creates a lightweight reference tag pointing directly to HEAD.', 1000, TRUE),
('10000000-0000-0000-0000-000000000023', 'Which command shows metadata and content changes for a specific Git object or commit?', 'easy', 'inspect', 'git show displays commit metadata, author, and diff changes for a specified revision.', 1000, TRUE),
('10000000-0000-0000-0000-000000000024', 'In Git architecture, what does the special pointer HEAD refer to?', 'easy', 'internals', 'HEAD points to the currently checked out branch or commit in your working directory.', 1000, TRUE),
('10000000-0000-0000-0000-000000000025', 'Which command removes a file from both the Git staging index and your local filesystem?', 'easy', 'removal', 'git rm <file> stages the deletion and deletes the file from the working tree.', 1000, TRUE),
('10000000-0000-0000-0000-000000000026', 'What characterizes a fast-forward merge in Git?', 'easy', 'merge', 'In a fast-forward merge, the target branch tip directly advances to source commit without a merge commit.', 1000, TRUE),
('10000000-0000-0000-0000-000000000027', 'Which git log option condenses each commit to a single line showing short hash and subject?', 'easy', 'log', 'git log --oneline outputs compact single-line commit summaries.', 1000, TRUE),
('10000000-0000-0000-0000-000000000028', 'In modern Git (2.23+), what command is recommended for switching branches instead of git checkout?', 'easy', 'checkout', 'git switch was introduced in Git 2.23 specifically for switching and creating branches.', 1000, TRUE),
('10000000-0000-0000-0000-000000000029', 'In modern Git (2.23+), what command discards uncommitted changes in your working tree?', 'easy', 'restore', 'git restore <file> restores working tree files to their staged or committed state.', 1000, TRUE),
('10000000-0000-0000-0000-000000000030', 'What hidden folder created by git init houses all repository databases, references, and configs?', 'easy', 'basics', 'The .git folder at the root of a repository contains all history, objects, and configurations.', 1000, TRUE),
('20000000-0000-0000-0000-000000000001', 'What is the fundamental difference between git merge and git rebase?', 'medium', 'rebase', 'git merge creates a dedicated merge commit preserving topology; rebase reapplies commits for linear history.', 1000, TRUE),
('20000000-0000-0000-0000-000000000002', 'What happens when you run git reset --soft HEAD~1?', 'medium', 'reset', '--soft moves the HEAD reference back by one commit while keeping modifications staged in the index.', 1000, TRUE),
('20000000-0000-0000-0000-000000000003', 'What happens when you run git reset --mixed HEAD~1 (the default reset mode)?', 'medium', 'reset', '--mixed moves HEAD and resets the index, leaving modified files intact in working tree unstaged.', 1000, TRUE),
('20000000-0000-0000-0000-000000000004', 'What happens when you run git reset --hard HEAD~1?', 'medium', 'reset', '--hard rewinds HEAD and completely overwrites both the index and working directory to target commit.', 1000, TRUE),
('20000000-0000-0000-0000-000000000005', 'Which command applies a single specific commit from another branch onto your active branch as a new commit?', 'medium', 'cherry-pick', 'git cherry-pick <commit> copies the changes introduced by an existing commit as a new commit on current branch.', 1000, TRUE),
('20000000-0000-0000-0000-000000000006', 'Which command records every movement of HEAD and branch tips locally, allowing recovery of deleted commits?', 'medium', 'reflog', 'git reflog tracks every update to local references, providing a recovery safety net.', 1000, TRUE),
('20000000-0000-0000-0000-000000000007', 'What does git clean -fd do in your repository?', 'medium', 'clean', 'git clean forcefully (-f) removes untracked files and untracked directories (-d).', 1000, TRUE),
('20000000-0000-0000-0000-000000000008', 'How does git revert <commit> differ from git reset <commit> regarding public branch safety?', 'medium', 'revert', 'git revert creates a new inverse commit preserving history, making it safe for published shared branches.', 1000, TRUE),
('20000000-0000-0000-0000-000000000009', 'What does git rebase -i HEAD~3 open in your editor?', 'medium', 'rebase-interactive', 'git rebase -i HEAD~3 opens an interactive todo list script allowing squash, reword, drop, or edit of last 3 commits.', 1000, TRUE),
('20000000-0000-0000-0000-000000000010', 'In an interactive rebase todo list, what does the squash command do?', 'medium', 'rebase-interactive', 'squash melds the commit into the previous commit and prompts you to combine the commit messages.', 1000, TRUE),
('20000000-0000-0000-0000-000000000011', 'In an interactive rebase todo list, how does fixup differ from squash?', 'medium', 'rebase-interactive', 'fixup melds the changes into previous commit like squash, but discards the fixup commit message.', 1000, TRUE),
('20000000-0000-0000-0000-000000000012', 'Why does git branch -d feature fail if feature contains unmerged commits, and how do you force delete it?', 'medium', 'branching', 'git branch -d protects against unmerged work loss; -D (or -d --force) overrides this safeguard.', 1000, TRUE),
('20000000-0000-0000-0000-000000000013', 'Which command deletes a remote branch named feature-auth on origin?', 'medium', 'remotes', 'git push origin --delete feature-auth requests the remote server to remove the branch ref.', 1000, TRUE),
('20000000-0000-0000-0000-000000000014', 'What information does git blame provide for a file?', 'medium', 'blame', 'git blame annotates each line with commit hash, author name, and timestamp of last modification.', 1000, TRUE),
('20000000-0000-0000-0000-000000000015', 'If you encounter unexpected merge conflicts, what command cleanly cancels the merge and restores pre-merge state?', 'medium', 'merge', 'git merge --abort resets index and working directory to state prior to starting the merge.', 1000, TRUE),
('20000000-0000-0000-0000-000000000016', 'After manually resolving conflicts during a rebase, what command should you execute?', 'medium', 'rebase', 'Stage resolved files with git add and run git rebase --continue (do not run git commit).', 1000, TRUE),
('20000000-0000-0000-0000-000000000017', 'What Git feature allows you to checkout multiple branches simultaneously in separate linked directories?', 'medium', 'worktree', 'git worktree allows multiple working trees linked to the same repository database.', 1000, TRUE),
('20000000-0000-0000-0000-000000000018', 'Which command initializes and fetches nested submodules after cloning a repository containing submodules?', 'medium', 'submodules', 'git submodule update --init --recursive clones and checks out nested submodules.', 1000, TRUE),
('20000000-0000-0000-0000-000000000019', 'What command creates a new branch named debug-fix directly from stash@{0} and drops the stash entry?', 'medium', 'stashing', 'git stash branch <branch> checks out the stash commit parent, applies stash, and drops it if clean.', 1000, TRUE),
('20000000-0000-0000-0000-000000000020', 'What condition causes a detached HEAD state in Git?', 'medium', 'internals', 'Checking out a specific commit hash, tag, or remote branch directly rather than a local named branch.', 1000, TRUE),
('20000000-0000-0000-0000-000000000021', 'In Git merge conflict markers, what content is enclosed between <<<<<<< HEAD and =======?', 'medium', 'merge', 'The changes present in your currently checked-out branch (HEAD) before the merge.', 1000, TRUE),
('20000000-0000-0000-0000-000000000022', 'What is a three-way merge in Git?', 'medium', 'merge', 'A merge algorithm comparing base commit, current branch commit, and incoming branch commit.', 1000, TRUE),
('20000000-0000-0000-0000-000000000023', 'How does an annotated tag (git tag -a) differ fundamentally from a lightweight tag?', 'medium', 'tags', 'Annotated tags create full Git tag objects containing tagger info, date, signature, and message.', 1000, TRUE),
('20000000-0000-0000-0000-000000000024', 'Why do created tags not appear on origin after git push origin main, and how do you push them?', 'medium', 'tags', 'Git does not automatically push tags; you must run git push origin --tags or push tag ref explicitly.', 1000, TRUE),
('20000000-0000-0000-0000-000000000025', 'Which git log command displays the commit topology as an ASCII text graph?', 'medium', 'log', 'git log --graph draws an ASCII graph showing branch and merge topology.', 1000, TRUE),
('20000000-0000-0000-0000-000000000026', 'Which command lists commit count summary per author in sorted descending order?', 'medium', 'log', 'git shortlog -sn groups commits by author, displays count (-n for numeric sort, -s for summary).', 1000, TRUE),
('20000000-0000-0000-0000-000000000027', 'Which command updates your local branch tracking refs and deletes stale references removed on origin?', 'medium', 'remotes', 'git fetch --prune removes local references to branches deleted on the remote repository.', 1000, TRUE),
('20000000-0000-0000-0000-000000000028', 'In Git config hierarchy, which configuration level takes highest precedence if a key is defined at all levels?', 'medium', 'config', 'Local config (.git/config) overrides global (~/.gitconfig), which overrides system (/etc/gitconfig).', 1000, TRUE),
('20000000-0000-0000-0000-000000000029', 'What does git diff branchA..branchB output?', 'medium', 'diff', 'Changes on branchB since it diverged from branchA or differences between both tips.', 1000, TRUE),
('20000000-0000-0000-0000-000000000030', 'What does the reword command in an interactive rebase todo list accomplish?', 'medium', 'rebase-interactive', 'reword uses the commit as-is but stops the rebase to let you edit the commit message.', 1000, TRUE),
('30000000-0000-0000-0000-000000000001', 'What binary search debugging command isolates the exact commit that introduced a regression?', 'hard', 'debugging', 'git bisect uses binary search through history between known good and bad revisions.', 1000, TRUE),
('30000000-0000-0000-0000-000000000002', 'How can you automate git bisect to test each commit non-interactively using an automated test script?', 'hard', 'debugging', 'git bisect run <script> runs automated binary search tests until bug commit is pinpointed.', 1000, TRUE),
('30000000-0000-0000-0000-000000000003', 'In Git object database (.git/objects), what are the four fundamental immutable object types?', 'hard', 'git-internals', 'Git stores all history in four content-addressed object types: Blobs, Trees, Commits, and Annotated Tags.', 1000, TRUE),
('30000000-0000-0000-0000-000000000004', 'In Git object database, what fundamental entity do Blob objects store?', 'hard', 'git-internals', 'Blobs store file data/content only; they do not store file names, directories, or permissions.', 1000, TRUE),
('30000000-0000-0000-0000-000000000005', 'What plumbing command inspects the type and human-readable content of any raw Git object hash?', 'hard', 'git-internals', 'git cat-file -p <hash> pretty-prints content of blob, tree, commit, or tag.', 1000, TRUE),
('30000000-0000-0000-0000-000000000006', 'What does the Git reference notation HEAD^2 refer to?', 'hard', 'git-internals', 'HEAD^2 refers to the second parent commit of a merge commit, whereas HEAD~2 refers to two generations prior.', 1000, TRUE),
('30000000-0000-0000-0000-000000000007', 'How does HEAD~3 differ from HEAD^^^ in commit revision navigation?', 'hard', 'git-internals', 'HEAD~3 and HEAD^^^ both refer to 3 generations prior along first parent lineage.', 1000, TRUE),
('30000000-0000-0000-0000-000000000008', 'What plumbing command prints the full 40-character SHA-1 object ID pointed to by HEAD?', 'hard', 'git-internals', 'git rev-parse HEAD parses the revision reference and outputs raw object hash.', 1000, TRUE),
('30000000-0000-0000-0000-000000000009', 'Which command checks repository database connectivity and identifies dangling/unreachable objects?', 'hard', 'git-internals', 'git fsck --lost-found verifies connectivity and writes dangling objects to .git/lost-found.', 1000, TRUE),
('30000000-0000-0000-0000-000000000010', 'What does git gc (garbage collection) perform within a repository?', 'hard', 'git-internals', 'Compresses loose objects into packfiles, consolidates packfile indexes, and prunes expired refs.', 1000, TRUE),
('30000000-0000-0000-0000-000000000011', 'What is Git rerere (reuse recorded resolution) used for?', 'hard', 'rerere', 'Records how you resolved a conflicted chunk and automatically resolves identical conflicts in future.', 1000, TRUE),
('30000000-0000-0000-0000-000000000012', 'What exit code must a Git hook script return to abort the current Git command (e.g. pre-commit)?', 'hard', 'hooks', 'Any non-zero exit code (e.g. 1) aborts the Git execution and prevents commit creation.', 1000, TRUE),
('30000000-0000-0000-0000-000000000013', 'Where are client-side Git hooks stored locally in a newly cloned or initialized repository?', 'hard', 'hooks', 'In the .git/hooks directory inside repository root.', 1000, TRUE),
('30000000-0000-0000-0000-000000000014', 'You accidentally pushed private credentials to a public branch. What is the safest and most permanent remediation?', 'hard', 'security', 'Purge the secret from all history with git-filter-repo/BFG, force push, and immediately revoke the secret.', 1000, TRUE),
('30000000-0000-0000-0000-000000000015', 'Which plumbing command writes current staging index state into a new Tree object in object database?', 'hard', 'plumbing', 'git write-tree writes staging index files into a tree object and prints its SHA-1 hash.', 1000, TRUE),
('30000000-0000-0000-0000-000000000016', 'Which plumbing command creates a new Commit object directly given a tree hash and parent commit hash?', 'hard', 'plumbing', 'git commit-tree <tree-hash> -p <parent-hash> -m "msg" creates a raw commit object.', 1000, TRUE),
('30000000-0000-0000-0000-000000000017', 'Which plumbing command calculates the SHA hash of a file and optionally writes it into .git/objects (-w)?', 'hard', 'plumbing', 'git hash-object computes object ID and with -w writes it into object database as a blob.', 1000, TRUE),
('30000000-0000-0000-0000-000000000018', 'What does git rebase --onto newbase upstream branch accomplish?', 'hard', 'rebase-onto', 'Takes commits on branch that diverged from upstream and replays them on top of newbase.', 1000, TRUE),
('30000000-0000-0000-0000-000000000019', 'By default, what is the retention period before git gc prunes unreachable reflog entries?', 'hard', 'internals', 'Default gc.reflogExpireUnreachable is 30 days (while reachable entries expire in 90 days).', 1000, TRUE),
('30000000-0000-0000-0000-000000000020', 'In monorepos, what Git feature allows checking out only a specific subset of directories or files?', 'hard', 'sparse-checkout', 'git sparse-checkout restricts working tree to specified directory patterns while keeping full history.', 1000, TRUE),
('30000000-0000-0000-0000-000000000021', 'What is a shallow clone created via git clone --depth 1?', 'hard', 'cloning', 'A clone truncated to only the latest commit snapshot without historical ancestry commits.', 1000, TRUE),
('30000000-0000-0000-0000-000000000022', 'What command packages repository commits and refs into a single transferable offline binary archive?', 'hard', 'bundle', 'git bundle create <file.bundle> packages refs and commits for offline sneaker-net git fetch.', 1000, TRUE),
('30000000-0000-0000-0000-000000000023', 'Which git commit flag signs a commit cryptographically using your configured GPG/SSH key?', 'hard', 'signatures', 'git commit -S (capital S) creates a cryptographically signed commit verified by git log --show-signature.', 1000, TRUE),
('30000000-0000-0000-0000-000000000024', 'What merge strategy is automatically invoked by Git when merging more than two head references at once?', 'hard', 'merge-strategies', 'The octopus merge strategy handles merges of 3 or more branches with no complex conflicts.', 1000, TRUE),
('30000000-0000-0000-0000-000000000025', 'What is the crucial difference between git merge -s ours vs git merge -X ours?', 'hard', 'merge-strategies', '-s ours records merge but discards all other branch changes; -X ours auto-resolves conflicts favoring our side.', 1000, TRUE),
('30000000-0000-0000-0000-000000000026', 'What command debugs why a specific file path is being ignored and outputs the matching .gitignore line?', 'hard', 'ignore', 'git check-ignore -v <path> prints the specific .gitignore file and line pattern responsible.', 1000, TRUE),
('30000000-0000-0000-0000-000000000027', 'Which plumbing command updates a branch reference to point directly to a new commit hash safely?', 'hard', 'plumbing', 'git update-ref refs/heads/<branch> <new-hash> safely updates reference files.', 1000, TRUE),
('30000000-0000-0000-0000-000000000028', 'What role does the packfile index (.idx file) serve in .git/objects/pack/?', 'hard', 'internals', 'Contains binary fan-out and hash lookup tables providing O(1) object offset searches in packfiles.', 1000, TRUE),
('30000000-0000-0000-0000-000000000029', 'In Git repository index (.git/index), what data is tracked for each staged file?', 'hard', 'internals', 'Tracks file path, SHA-1 blob hash, permissions mode, and stat cache (ctime, mtime, size, inode).', 1000, TRUE),
('30000000-0000-0000-0000-000000000030', 'What command verifies the cryptographic integrity and packing of Git packfiles on disk?', 'hard', 'git-internals', 'git verify-pack -v verifies packfile structure and prints per-object compression statistics.', 1000, TRUE)
